export function getResponsiveImageProps(
  src: string,
  archetype?: string,
  isFullBleed?: boolean,
): {
  src: string;
  srcSet?: string;
  webpSrcSet?: string;
  sizes: string;
  aspectRatio?: number;
} {
  // تكبير قيمة أحجام العرض المطلوبة (sizes) لإجبار المتصفح على اختيار دقة أعلى (1400w) في كافة التصاميم
  let sizes = "100vw";
  if (
    isFullBleed ||
    archetype === "cinematic-anchor" ||
    archetype === "full-bleed-moment"
  ) {
    sizes = "100vw";
  } else if (
    archetype === "tall-staggered-right" ||
    archetype === "narrative-offset-left"
  ) {
    sizes = "(max-width: 768px) 100vw, (max-width: 1280px) 70vw, 1000px";
  } else if (archetype === "staggered-offset-right") {
    sizes = "(max-width: 768px) 100vw, (max-width: 1280px) 80vw, 1200px";
  } else if (
    archetype === "compact-staggered-left" ||
    archetype === "split-editorial"
  ) {
    sizes = "(max-width: 768px) 100vw, (max-width: 1280px) 85vw, 1200px";
  } else {
    sizes = "(max-width: 768px) 100vw, (max-width: 1280px) 90vw, 1400px";
  }

  if (!src) {
    return { src: "", sizes };
  }

  const matchedKey = Object.keys(IMAGE_MANIFEST).find((key) => {
    const baseName = key.replace(/\.[^.]+$/, "");
    return typeof src === "string" && src.includes(baseName);
  });

  if (matchedKey && IMAGE_MANIFEST[matchedKey]) {
    const spec = IMAGE_MANIFEST[matchedKey];
    return {
      src: spec.src || src,
      srcSet: spec.fallbackSrcSet,
      webpSrcSet: spec.webpSrcSet,
      sizes,
      aspectRatio: spec.aspectRatio,
    };
  }

  if (typeof src === "string" && src.includes("unsplash.com")) {
    const cleanUrl = src.split("?")[0];
    const webpSrcSet = `${cleanUrl}?w=640&auto=format&q=85 640w, ${cleanUrl}?w=960&auto=format&q=85 960w, ${cleanUrl}?w=1400&auto=format&q=85 1400w`;
    return {
      src: `${cleanUrl}?w=1400&auto=format&q=85`,
      webpSrcSet,
      sizes,
    };
  }

  return {
    src,
    sizes,
  };
}